class Solution {
    private int[][][] memo;
    private char[] a;
    private char[] b;
    private int n;

    public boolean isScramble(String s1, String s2) {
        if (s1 == null || s2 == null) return false;
        if (s1.length() != s2.length()) return false;
        n = s1.length();
        a = s1.toCharArray();
        b = s2.toCharArray();
        memo = new int[n][n][n + 1];
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                for (int k = 0; k <= n; ++k)
                    memo[i][j][k] = -1;
        return dfs(0, 0, n);
    }

    private boolean dfs(int i1, int i2, int len) {
        if (memo[i1][i2][len] != -1) return memo[i1][i2][len] == 1;
        // If substrings are equal, true
        if (equalSegment(i1, i2, len)) {
            memo[i1][i2][len] = 1;
            return true;
        }
        // Prune by character counts
        if (!sameCharCounts(i1, i2, len)) {
            memo[i1][i2][len] = 0;
            return false;
        }
        // Try all splits
        for (int k = 1; k < len; ++k) {
            // no swap
            if (dfs(i1, i2, k) && dfs(i1 + k, i2 + k, len - k)) {
                memo[i1][i2][len] = 1;
                return true;
            }
            // swap
            if (dfs(i1, i2 + len - k, k) && dfs(i1 + k, i2, len - k)) {
                memo[i1][i2][len] = 1;
                return true;
            }
        }
        memo[i1][i2][len] = 0;
        return false;
    }

    private boolean equalSegment(int i1, int i2, int len) {
        for (int i = 0; i < len; ++i) {
            if (a[i1 + i] != b[i2 + i]) return false;
        }
        return true;
    }

    private boolean sameCharCounts(int i1, int i2, int len) {
        int[] cnt = new int[26];
        for (int i = 0; i < len; ++i) {
            cnt[a[i1 + i] - 'a']++;
            cnt[b[i2 + i] - 'a']--;
        }
        for (int v : cnt) if (v != 0) return false;
        return true;
    }
